// MainB.java
class Produk {
    String nama;
    int harga;

    Produk(String nama, int harga) {
        this.nama = nama;
        this.harga = harga;
    }

    int totalBayar(int jumlah) {
        return harga * jumlah;
    }
}

public class MainB {
    public static void main(String[] args) {
        Produk p = new Produk("Keripik", 10000);
        System.out.println(p.nama + " x5 = " + p.totalBayar(5));
    }
}

